package csvwriter

import (
	"encoding/csv"
	"fmt"
	"io"
	"iter"
	"log/slog"

	"github.com/p4rtridge/p4rse_tan/core"
	"github.com/p4rtridge/p4rse_tan/logger"
)

// Export represents a streaming schema for CSV formulation
type Export struct {
	Filename string
	Header   []string
	Stream   iter.Seq[[]string]
}

// KeyExport signals the CSV data parameters generated by upstream business logic plugins
var KeyExport = core.NewTypedKey[Export]("csv_export")

// Plugin translates generic core.Plugin outputs recursively into native CSV byte slices.
type Plugin struct {
	Input  core.Plugin
	Output core.Plugin
}

func (p *Plugin) Name() string { return "CSVWriterPlugin" }

func (p *Plugin) Requires() []core.DataKey {
	var keys []core.DataKey
	if p.Input != nil {
		keys = append(keys, p.Input.Requires()...)
	}
	if p.Output != nil {
		for _, req := range p.Output.Requires() {
			if req != core.KeyExport.Key {
				keys = append(keys, req)
			}
		}
	}
	return keys
}

func (p *Plugin) Provides() []core.DataKey {
	var keys []core.DataKey
	if p.Input != nil {
		for _, prov := range p.Input.Provides() {
			if prov != KeyExport.Key {
				keys = append(keys, prov)
			}
		}
	}
	if p.Output != nil {
		keys = append(keys, p.Output.Provides()...)
	}
	return keys
}

func (p *Plugin) Cleanup(ctx core.Context) error {
	if p.Input != nil {
		if err := p.Input.Cleanup(ctx); err != nil {
			return err
		}
	}
	if p.Output != nil {
		if err := p.Output.Cleanup(ctx); err != nil {
			return err
		}
	}
	return nil
}

func (p *Plugin) Execute(ctx core.Context) error {
	log := logger.FromContext(ctx).With(slog.String("plugin", p.Name()))

	if p.Input == nil {
		return csvErr("missing input plugin", nil)
	}

	if p.Output == nil {
		return csvErr("missing output plugin", nil)
	}

	log.Debug("[DEBUG] executing input plugin", slog.String("input", p.Input.Name()))
	if err := p.Input.Execute(ctx); err != nil {
		return csvErr("input execution failed", err)
	}

	data, err := KeyExport.Get(ctx)
	if err != nil {
		return csvErr("export missing", err)
	}

	log.Debug("[DEBUG] setting up csv pipe",
		slog.String("filename", data.Filename),
		slog.Any("header", data.Header),
	)

	pr, pw := io.Pipe()

	core.KeyExport.Set(ctx, core.Export{
		Name:   data.Filename,
		Reader: pr,
	})

	log.Debug("[DEBUG] executing output plugin", slog.String("output", p.Output.Name()))
	if err := p.Output.Execute(ctx); err != nil {
		pw.Close()
		return csvErr("output execution failed", err)
	}

	eg, _ := core.KeyErrGroup.Get(ctx)
	if eg == nil {
		return csvErr("errgroup missing from context", nil)
	}

	eg.Go(func() error {
		defer pw.Close()

		writer := csv.NewWriter(pw)
		if err := writer.Write(data.Header); err != nil {
			return csvErr("header write failed", err)
		}

		for row := range data.Stream {
			if err := writer.Write(row); err != nil {
				return csvErr("row write failed", err)
			}
		}

		writer.Flush()
		log.Debug("[DEBUG] csv stream flushed", slog.String("filename", data.Filename))

		return nil
	})

	return nil
}

func csvErr(reason string, cause error) error {
	if cause == nil {
		return fmt.Errorf("csvwriter %s", reason)
	}
	return fmt.Errorf("csvwriter %s: %w", reason, cause)
}
